 <tr class="hover:bg-slate-800/35"><td class="p-4"><div class="flex items-center gap-3"><span class="grid place-items-center w-9 h-9 rounded-full <?=$online?'bg-cyan-500/20 text-cyan-300':'bg-slate-800 text-slate-500'?>"><?=strtoupper(substr($account['username'],0,1))?></span><div><strong><?=$e($account['username'])?></strong><div class="text-xs text-slate-500">#<?=$account['id']?> · <?=$e($account['allowed_ip']?:'cualquier IP')?></div></div></div></td><td><div><?=$e($account['owner_name']?:'Administración')?></div><div class="text-xs text-slate-500 max-w-56 truncate" title="<?=$e($account['packages']??'')?>"><?=$e($account['packages']?:'Sin package')?></div></td><td class="text-center"><span class="inline-flex border rounded-full px-2.5 py-1 text-xs <?=$statusStyle[$account['status']]??$statusStyle['blocked']?>"><?=$e($account['status'])?></span></td><td class="text-center"><span class="inline-flex items-center gap-2 <?=$online?'text-emerald-400':'text-slate-500'?>"><i class="w-2 h-2 rounded-full <?=$online?'bg-emerald-400 animate-pulse':'bg-slate-600'?>"></i><?=$online?'Online':'Offline'?></span></td><td class="text-center"><strong class="<?=$online?'text-cyan-400':''?>"><?=$account['active_sessions']?></strong><span class="text-slate-600"> / </span><?=$account['max_connections']?></td><td class="text-center <?=$soon?'text-red-400':''?>"><?=$account['expires_at']?$e(date('Y-m-d H:i',strtotime($account['expires_at']))):'<span class="text-slate-500">Sin límite</span>'?></td><td><div class="max-w-56 truncate"><?=$online&&$account['watching_title']?$e($account['watching_title']):'<span class="text-slate-500">Sin reproducción</span>'?></div><div class="text-xs text-slate-500"><?=$account['last_connection']?$e(date('Y-m-d H:i',strtotime($account['last_connection']))):'Nunca se conectó'?><?=$account['watching_type']?' · '.$e($account['watching_type']):''?></div></td><td class="p-3"><div class="flex justify-end gap-1"><?php if(\App\Security\Auth::can('accounts.secrets.view')):?><button title="Datos de conexión" class="bg-indigo-700 hover:bg-indigo-600 px-2.5 py-2 rounded" @click="fetch('/accounts/reveal',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_csrf=<?=rawurlencode($csrf->token())?>&id=<?=$account['id']?>'}).then(r=>r.json()).then(r=>{secretText=r.error||('Servidor: '+r.server+'\nUsuario: '+r.username+'\nContraseña: '+r.credential+'\n\nM3U:\n'+r.m3u+'\n\nEPG:\n'+r.epg);secretOpen=true})">Datos</button><?php endif?><?php if(\App\Security\Auth::can('accounts.update')):?><form method="post" action="/accounts/renew"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$account['id']?>"><input type="hidden" name="days" value="30"><button title="Renovar 30 días" class="bg-emerald-700 hover:bg-emerald-600 px-2.5 py-2 rounded">+30d</button></form><form method="post" action="/accounts/status"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$account['id']?>"><input type="hidden" name="status" value="<?=$account['status']==='suspended'?'active':'suspended'?>"><button title="<?=$account['status']==='suspended'?'Activar':'Suspender'?>" class="bg-amber-700 hover:bg-amber-600 px-2.5 py-2 rounded"><?=$account['status']==='suspended'?'Activar':'Pausar'?></button></form><?php endif?><?php if($online&&\App\Security\Auth::can('sessions.disconnect')):?><form method="post" action="/accounts/disconnect" onsubmit="return confirm('¿Desconectar todas las sesiones de esta línea?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$account['id']?>"><button title="Desconectar" class="bg-red-800 hover:bg-red-700 px-2.5 py-2 rounded">Cortar</button></form><?php endif?></div></td></tr><?php endforeach?><?php if(!$accounts):?><tr><td colspan="8" class="p-12 text-center text-slate-500">No se encontraron líneas con estos filtros.</td></tr><?php endif?></tbody></table></div>
